-- ============================================================================
-- Yuno CRM — analyse client : codes postaux de France → coordonnées (2026-10-07).
--
-- Sert à la distance entre un client et sa soirée (familles « a fait la
-- route » et « de passage »). Aucun appel réseau au calcul : tout est ici.
--
-- Sources (données ouvertes, téléchargées le 07/10/2026) :
--   • Base officielle des codes postaux, La Poste (data.gouv.fr, jeu
--     « base-officielle-des-codes-postaux », Licence Ouverte / Open Licence
--     v2.0 d'Etalab) : la liste des codes postaux ;
--   • API Découpage administratif (geo.api.gouv.fr/communes, DINUM, données
--     IGN / INSEE, Licence Ouverte v2.0) : le centre de chaque commune et ses
--     codes postaux.
-- Un code postal = le centre de ses communes pondéré par leur population
-- (6 310 codes sur les 6 328 de la base La Poste ; les 18 manquants sont des
-- codes sans commune rattachée). Paris, Lyon et Marseille ne sont qu'une
-- commune chacune : tous leurs codes postaux ont le centre de la ville, ce
-- qui suffit à des seuils de 50 km et plus.
-- ============================================================================

CREATE TABLE IF NOT EXISTS public.crm_postal_codes_fr (
  cp  text PRIMARY KEY CHECK (cp ~ '^[0-9]{5}$'),
  lat double precision NOT NULL,
  lng double precision NOT NULL
);
ALTER TABLE public.crm_postal_codes_fr ENABLE ROW LEVEL SECURITY;
-- Aucune policy : lue par le moteur d'analyse (SECURITY DEFINER) seulement.

ON CONFLICT (cp) DO UPDATE SET lat = EXCLUDED.lat, lng = EXCLUDED.lng;
